local F=dofile('tests/fixtures/addon.lua');local test,finish=F.suite()
local function fixture()
    local f=F.new();local a=f.addon;f.load('UI/settings_draft.lua');f.load('Options/custom_condition.lua')
    local h=io.open('Core/custom_authoring.lua');if h then h:close();f.load('Core/custom_authoring.lua') end
    a.name='rotationmaster';f.env.rotationmaster=a;a.funcDeserialize={};f.env.loadstring=function(text,name) local fn,why=loadstring(text,name);if fn then setfenv(fn,f.env) end;return fn,why end
    return f,a
end
test('schema text parses nested unions records and legacy item fields without executing Lua',function()
    local f,a=fixture();assert(a.ParseCustomFieldSchema,'schema parser missing');local fields=assert(a:ParseCustomFieldSchema('{ spell = { string, number }, target = { unit = string, checks = condition[] } }'))
    assert(fields.spell[2]=='number' and fields.target.checks=='condition[]');local text=a:FormatCustomFieldSchema(fields);local again=assert(a:ParseCustomFieldSchema(text));assert(again.target.unit=='string')
    assert(not a:ParseCustomFieldSchema('{ field = (function() error("never") end)() }'));assert(not a:ParseCustomFieldSchema('{ x = string, x = number }'));assert(not a:ParseCustomFieldSchema('{ x = { string, nested = number } }'));assert(not a:ParseCustomFieldSchema(string.rep('{',40)))
end)
test('compile-only checks all callbacks without executing their bodies or hooks',function()
    local f,a=fixture();assert(a.ValidateCustomConditionSource,'compiler missing');local source=a:CopySettingsData(a.empty_condition);source.description='Test';source.fields={items='{ string, { string, number } }'};source.on_register='error("MUST NOT RUN")';source.evaluate='error("MUST NOT RUN")'
    local checked=assert(a:ValidateCustomConditionSource('CUSTOM',source));assert(checked.valid and checked.compiled.on_register);assert(a.definitions.CUSTOM==nil)
    source.print='return )';local ok,why=a:ValidateCustomConditionSource('CUSTOM',source);assert(not ok and why.callback=='print' and a.definitions.CUSTOM==nil)
end)
test('installation preserves existing definition and source if compilation or registration fails',function()
    local f,a=fixture();local old={description='Before'};local source=a:CopySettingsData(a.empty_condition);source.description='After';source.evaluate='return true';a.db.global.custom_conditions={CUSTOM={description='Before source'}};a.conditionDefinitions={CUSTOM=old};a.RegisterCondition=function(self,key,value) self.conditionDefinitions[key]=value;value.on_register(key) end
    source.on_register='error("hook failed")';local ok=a:InstallCustomCondition('CUSTOM',source,old);assert(not ok and a.conditionDefinitions.CUSTOM==old and a.db.global.custom_conditions.CUSTOM.description=='Before source')
    source.on_register='';assert(a:InstallCustomCondition('CUSTOM',source,old));assert(a.db.global.custom_conditions.CUSTOM.description=='After' and a.conditionDefinitions.CUSTOM.evaluate({})==true)
end)
test('authoring draft has bounded history across callbacks and detects external replacements',function()
    local f,a=fixture();local source=a:CopySettingsData(a.empty_condition);source.description='Original';local d=a:NewCustomConditionDraft('CUSTOM',source);assert(not d:IsDirty());d:SetFunction('evaluate','return 1');d:SetFunction('print','return "changed"');assert(d:IsDirty());assert(d:Undo() and d.value.evaluate=='return 1' and d.value.print==source.print);assert(d:Undo() and not d:IsDirty());assert(d:Redo());d:SetFunction('evaluate','return 2');assert(not d:Redo());source.description='external';assert(d.value.description=='Original')
end)
test('production registry rollback preserves the previous callback after a failing registration hook',function()
    local f,a=fixture();f.load('Core/conditions.lua');local previous={description='Before',fields={},evaluate=function() return true end};a:RegisterCondition('CUSTOM',previous);a.db.global.custom_conditions={CUSTOM={description='Before source'}};local source=a:CopySettingsData(a.empty_condition);source.description='After';source.on_register='error("hook failed")';assert(not a:InstallCustomCondition('CUSTOM',source,previous));assert(a.conditionDefinitions.CUSTOM==previous and a.db.global.custom_conditions.CUSTOM.description=='Before source')
end)
test('missing compiler reports unavailable without changing source or registry',function()
    local f,a=fixture();f.env.loadstring=false;local source=a:CopySettingsData(a.empty_condition);source.description='Test';local ok,why=a:ValidateCustomConditionSource('CUSTOM',source);assert(not ok and why.reason=='compiler-unavailable')
end)
test('registration failures reach RM diagnostics with custom source redacted',function()
    local f,a=fixture();f.load('Diagnostics/errors.lua');local source=a:CopySettingsData(a.empty_condition);source.description='Test';source.on_register='error("PRIVATE_SOURCE_FRAGMENT")';a.db.global.custom_conditions={};a.conditionDefinitions={};a.RegisterCondition=function(self,key,value) self.conditionDefinitions[key]=value;value.on_register(key) end
    assert(not a:InstallCustomCondition('CUSTOM',source,nil));assert(#a.Diagnostics:GetReports()==1 and not a.Diagnostics:FormatReport():find('PRIVATE_SOURCE_FRAGMENT',1,true) and a.Diagnostics:FormatReport(nil,true):find('PRIVATE_SOURCE_FRAGMENT',1,true))
end)
test('existing startup registration shares the staged compiler and canonical field declarations',function()
    local f,a=fixture();local source=a:CopySettingsData(a.empty_condition);source.description='Test';source.fields={items='{ string, { string, number } }'};assert(a:register_custom_condition('CUSTOM',source));assert(type(a.definitions.CUSTOM.fields.items)=='table' and a.definitions.CUSTOM.fields.items[2][2]=='number' and source.fields.items=='{ string, { string, number } }')
end)
test('startup compatibility preserves generated duplicate IDs and older large sources',function()
    local f,a=fixture();local source=a:CopySettingsData(a.empty_condition);source.description=string.rep('old description ',90);source.evaluate='--'..string.rep('x',70000)..'\nreturn true';source.fields={['legacy-field']='number'};local key='CUSTOM_'..a:uuid():gsub('-','_');assert(a:register_custom_condition(key,source),'UUID duplicate stopped registering');assert(a.definitions[key].fields['legacy-field']=='number');local long=string.rep('CUSTOM',60);assert(a:register_custom_condition(long,source));assert(a:ParseCustomFieldSchema(assert(a:FormatCustomFieldSchema(source.fields)))['legacy-field']=='number')
end)
test('saved source collisions need an explicit matching baseline even without a runtime entry',function()
    local f,a=fixture();local old={description='Saved old'};a.db.global.custom_conditions={COLLISION=old};a.conditionDefinitions={};a.RegisterCondition=function(self,key,value) self.conditionDefinitions[key]=value end;local source=a:CopySettingsData(a.empty_condition);source.description='New';assert(not a:InstallCustomCondition('COLLISION',source,nil) and a.db.global.custom_conditions.COLLISION==old);assert(not a:InstallCustomCondition('COLLISION',source,nil,{description='Wrong'}));assert(a:InstallCustomCondition('COLLISION',source,nil,a:CopySettingsData(old)) and a.db.global.custom_conditions.COLLISION.description=='New')
end)
test('callback wrapper escape is rejected without running expressions in a source preview compile',function()
    local f,a=fixture();local source=a:CopySettingsData(a.empty_condition);source.description='Test';source.evaluate='end, (function() previewExecuted=true end)(), function()'
    assert(not a:CompileCustomCondition('ESCAPE',source) and not f.env.previewExecuted,'condition body escaped the compile-only boundary')
end)
test('callback signatures expose full standard arguments while preserving old authored parameter aliases',function()
    local f,a=fixture();local source=a:CopySettingsData(a.empty_condition);source.description='Contract';source.parameters={evaluate={'candidate','cache'},print={'_','value'}}
    source.evaluate='return candidate == value and evalStart == 55';source.print='return tostring(spec)..":"..tostring(_)'
    assert(a:CustomConditionSignature(source,'evaluate')=='function(value, cache, evalStart)' and a:CustomConditionSignature(source,'print')=='function(spec, value)')
    local definition=assert(a:CompileCustomCondition('CONTRACT',source));assert(definition.evaluate({}, {},55)==true and definition.print(7,{})=='7:7')
end)
test('editor whitespace normalization keeps multiline literal values unchanged',function()
    local f,a=fixture();f.load('LibsAugment/FAIAP.lua')
    local code='\n        return [=[\n        literal whitespace stays\n          inside the string |c12345678\n        ]=]\n'
    local normalized=a:NormalizeLuaSourceForEditor(code);assert(normalized:sub(1,6)=='return');assert(assert(loadstring(code))()==assert(loadstring(normalized))(),'editor formatting changed a multiline literal')
end)
finish()
